/** Replay and delivery use one complete AP predicate after their candidate scans. */
fun matches(sub: Subscription, pub: Publication, member: Int, ops: ApOps, mode: ApMode): Facts? {
    ops.manager.cancellation.checkpoint()
    if (!RuntimeDataDomain.packet(sub.ref.premise, sub.added) ||
        !RuntimeDataDomain.packet(pub.premise, pub.conclusion)) return null
    return if (sub.zeroOnly) sub.added.takeIf { pub.premise.isZero }
    else ops.satisfying(sub.added, pub.premise.member(member), mode)
}

private fun enterCallees(ctx: CallContext, stage: CallStage.Callees, fact: PlanFact) {
    val core = active()
    val ref = CallerRef(core.key, fact.premise, ctx.callerLayer, ctx.node, ctx.plan.stages.indexOf(stage), core.scope)
    for (callee in stage.callees) {
        core.ap.cancellation.checkpoint()
        val part = Subscription(callee, ref, fact.facts.layer, fact.facts)
        if (!RuntimeDataDomain.packet(ref.premise, fact.facts)) continue
        check(part.added.base !is AccessPathBase.CleanerTemporary) {
            "A field-action temporary cannot enter an added link"
        }
        check(part.linkLayer == part.added.layer) { "The link layer must be the added fact's layer" }
        if (core.config.run1) {
            core.runnerPort.subscribe(part)
            core.ap.cancellation.checkpoint()
            core.runnerPort.link(callee, ref, part.linkLayer, part.added)
            continue
        }

        val statistics = core.context.shared.n2Statistics
        statistics?.selectedCallOffered()
        // Saved NORMAL records apply to every offer, without standing input admission.
        replayPersistedSummaries(core.config, core.ops, part, core, statistics)
        if (core.forward) for ((row, member) in core.config.normalTargets.candidates(callee, part, core.mode)) {
            core.ap.cancellation.checkpoint()
            if (!row.premise.isZero) applyTarget(part, row, member, saved = true)
        }
        // Demand admission uses the complete original offer, never a live merge delta.
        val initials = emitRestrictedInitials(core.config, core.ops, callee, part.added, statistics)
        if (initials.isEmpty()) continue

        // Register before a same-unit callee can publish. Current replay remains fresh-only.
        core.runnerPort.subscribe(part)
        core.ap.cancellation.checkpoint()
        // A duplicate live offer can still carry a complete initial packet.
        statistics?.initialPacketOffered(initials.size)
        core.runnerPort.startInitials(callee, initials)
    }
}

private val targetJoins = HashMap<TargetJoinKey, KaryJoin<TargetBinding>>()

override fun applyTarget(part: Subscription, row: TargetSummary, member: Int) =
    applyTarget(part, row, member, saved = false)

private fun applyTarget(part: Subscription, row: TargetSummary, member: Int, saved: Boolean) {
    val core = active()
    if (!core.forward && row.target is Target.NormalTarget) return
    if (!RuntimeDataDomain.packet(part.ref.premise, part.added) || !RuntimeDataDomain.premise(row.premise)) return
    val initial = row.premise.member(member)
    if (part.zeroOnly && !initial.isZero) return
    val selected = core.ops.satisfying(part.added, initial, core.mode,
        record = saved && initial.tail != Tail.ANY_TAINT) ?: return
    val layer = if (part.ref.callerLayer == Layer.DEMAND || selected.layer == Layer.DEMAND ||
        part.linkLayer == Layer.DEMAND) Layer.DEMAND else Layer.NORMAL
    if (row.target is Target.NormalTarget && layer != Layer.NORMAL) return
    val binding = TargetBinding(part.ref, layer)
    if (row.premise is InitialAp) emitTargetBinding(listOf(binding), row.target)
    else {
        val key = TargetJoinKey(part.callee, row.premise, row.target, part.ref.call, part.ref.stageOrdinal, saved, part.ref.scope)
        val join = targetJoins.getOrPut(key) { KaryJoin(row.premise.size, core.ap.cancellation) }
        for (bindings in join.add(member, binding)) emitTargetBinding(bindings, row.target)
    }

 * Keep the raw selected packet for ordinary request callbacks. */
private data class MatchedInput(val input: Input, val facts: Facts)
private fun queueData(offered: Input, exit: PortId, row: Publication, member: Int,
                      cache: MutableMap<InitialAp, MatchedInput?>) {
    matchStatistics?.let { it.candidatePairs++ }
    val initial = row.premise.member(member)
    if (!cache.containsKey(initial)) {
        val input = if (isStaticControl(offered) && initial.base == STATIC)
            suppliedStaticInput(offered, initial) else offered
        matchStatistics?.let { it.nativeMatches++ }
        cache[initial] = ops.satisfying(input.value, initial, mode)?.let { MatchedInput(input, it) }
    }
    val matched = cache[initial] ?: return
    deliveries += Delivery.Data(matched.input, exit, row, member, matched.facts)
}

private fun deliver(delivery: Delivery.Data) {
    val (input, exit, row, member, matchedInput) = delivery
    // A different geometry has a different loop growth classification.
    for (scalar in annotatedLoopScalars(ops, row.conclusion)) {
        val geometry = ops.leaves(scalar).single()
        when (val premise = row.premise) {
            is InitialAp -> application.applyMatched(matchedInput, input.link.original, premise, scalar,
                output(input, exit, premise, geometry))
            is PremiseSet -> {
                check(!mode.run1 && mode.direction == Direction.FORWARD)
                val matched = matchedInput as? TaintTree ?: continue
                val key = NdKey(input.link.parent, input.link.point, exit, premise, scalar.layer)
                val join = joins.getOrPut(key) { NdSummaryJoin(ap, premise.size) }
                val binding = NdInput(input.link, premise.member(member), matched.layer).also { it.matched = matched }
                fun emit(parts: List<NdInput>, value: TaintTree) {
                    matchStatistics?.let { it.ndCombinations++ }
                    var original: PremiseKey = ap.zero
                    for (part in parts) original = ap.union(original, part.link.original)
                    val complete = Input(input.link.copy(original = original), input.value)
                    for (piece in annotatedLoopScalars(ops, value))
                        application.applyCombination(parts.map { LocalRelationBinding(it.link.original, it.initial, it.matched) },
                            piece as TaintTree, output(complete, exit, premise, ops.leaves(piece).single()))
                }
                for ((parts, value) in join.addSubscription(member, binding) { prior, offered ->
                    val (merged, delta) = ap.mergeAddDelta(prior.matched, offered.matched)
                    prior.matched = merged as TaintTree
                    delta != null
                }) emit(parts, value)
                for ((parts, value) in join.addConclusion(scalar as TaintTree)) emit(parts, value)
            }
        }
    }
}

